(function(){try{
	var H={};
	H.norm=function(s){return String(s==null?"":s).replace(/\s+/g," ").trim();};
	H.sleep=function(ms){return new Promise(function(r){setTimeout(r,ms);});};
	H.until=async function(fn,ms){var t0=Date.now();var lim=Number(ms)||8000;while(Date.now()-t0<lim){var v=false;try{v=fn()===true;}catch(e){v=false;}if(v){return true;}await H.sleep(60);}return false;};
	H.sel=function(label){var want=H.norm(label);var all=document.querySelectorAll("select");var i=0;var s=null;
		for(i=0;i<all.length;i++){s=all[i];if(H.norm(s.getAttribute("aria-label")||"")===want){return s;}if(H.norm(s.getAttribute("name")||"")===want){return s;}}
		var best=null;var bd=99;
		for(i=0;i<all.length;i++){s=all[i];var box=s.closest("div");var p=box?box.parentElement:null;
			for(var up=0;p&&up<5;up+=1){if(H.norm(p.textContent).indexOf(want)>=0){if(up<bd){bd=up;best=s;}break;}p=p.parentElement;}}
		return best;};
	H.nopt=function(label){var s=H.sel(label);return s?s.options.length:-1;};
	H.opts=function(label){var s=H.sel(label);if(!s){return "__NOSEL__";}var o=[];for(var i=0;i<s.options.length;i++){o.push(H.norm(s.options[i].textContent));}return o.join("|");};
	H.nsel=function(label){var s=H.sel(label);return s?s.selectedOptions.length:-1;};
	H.trigger=function(label){var s=H.sel(label);if(!s){return "nosel";}var box=s.closest("div");var base=box?box.parentElement:null;if(!base){return "nobase";}var b=base.querySelector("button");if(!b){return "notrigger";}b.click();return "clicked";};
	H.optEls=function(){var a=document.querySelectorAll('[role="option"]');if(a.length){return a;}return document.querySelectorAll('[role="listbox"] [role="option"], [role="listbox"] li');};
	H.optCount=function(){var n=H.optEls().length;if(n){return n;}return document.querySelectorAll('[role="listbox"] b').length;};
	H.optReady=function(n){return H.optCount()>=(Number(n)||1);};
	H.opt=function(needle){var os=H.optEls();var want=H.norm(needle);for(var i=0;i<os.length;i++){if(H.norm(os[i].textContent).indexOf(want)>=0){os[i].click();return "clicked";}}return "noopt";};
	H.optB=function(limit){var bs=document.querySelectorAll('[role="option"] b');if(!bs.length){bs=document.querySelectorAll('[role="listbox"] b');}var o=[];for(var i=0;i<bs.length&&i<(Number(limit)||99);i++){o.push(H.norm(bs[i].textContent));}return o.join("|");};
	H.card=function(title){var hs=document.querySelectorAll("h4");var want=H.norm(title);for(var i=0;i<hs.length;i++){if(H.norm(hs[i].textContent)!==want){continue;}var b=hs[i].parentElement;for(var up=0;b&&up<8;up+=1){if(b.querySelector("button")){return b;}b=b.parentElement;}return hs[i].parentElement;}return null;};
	H.cardBtn=function(title,label){var c=H.card(title);if(!c){return "nocard";}var bs=c.querySelectorAll("button");var want=H.norm(label);for(var i=0;i<bs.length;i++){if(H.norm(bs[i].textContent)===want){bs[i].click();return "clicked";}}return "nobtn";};
	H.tab=function(text){var ts=document.querySelectorAll('[role="tab"]');var want=H.norm(text);for(var i=0;i<ts.length;i++){if(H.norm(ts[i].textContent)===want){ts[i].click();return "clicked";}}return "notab";};
	H.dlgBtn=function(label){var ds=document.querySelectorAll('[role="dialog"]');var want=H.norm(label);for(var k=0;k<ds.length;k++){var d=ds[k];if(d.hasAttribute("hidden")){continue;}var bs=d.querySelectorAll("button");for(var i=0;i<bs.length;i++){if(H.norm(bs[i].textContent)===want){bs[i].click();return "clicked";}}}return "nobtn";};
	H.mark=function(id){window.__T=window.__T||{};window.__T[id]="done";return "marked";};
	H.marked=function(id){return !!(window.__T&&window.__T[id]==="done");};
	H.trace=function(id,v){window.__T=window.__T||{};window.__T[id]=String(v);return String(v);};
	// 选一个 HeroUI Select 的值：先走隐藏 <select> 的 change（库源实测：onChange ⇒ setSelectedKeys ＋
	// 应用 onChange），verify 不成立就退回 popover＋点 option（库源实测：useSelectableItem.onPress）。
	// 返回哨兵串，让 setup 的读数自己说明走了哪条路（fail-closed，不静默算成功）。
	H.choose=async function(label,value,optNeedle,verify){var s=H.sel(label);if(!s){return "nosel";}
		s.value=String(value);s.dispatchEvent(new Event("change",{bubbles:true}));
		var ok=false;try{ok=await H.until(function(){return verify()===true;},6000);}catch(e){ok=false;}
		if(ok){return "native";}
		var t=H.trigger(label);if(t!=="clicked"){return "native_fail+"+t;}
		var opened=false;try{opened=await H.until(function(){return H.optCount()>0;},6000);}catch(e){opened=false;}
		if(!opened){return "native_fail+nopopover";}
		var c=H.opt(optNeedle);if(c!=="clicked"){return "native_fail+noopt";}
		var ok2=false;try{ok2=await H.until(function(){return verify()===true;},6000);}catch(e){ok2=false;}
		return ok2?"popover":"both_fail";};
	window.__H=H;return true;
	}catch(e){return "__ERR__:"+String(e&&e.message?e.message:e).slice(0,80);}})()

